1	// Engine entry point. Streams the prove-or-refuse run as EngineEvent values.
2	//
3	// runEngine is an async generator so the API route can stream each event and the
4	// UI can fill the coverage matrix live. The flow: parse the criteria, then for
5	// each one run two independent evidence passes with Promise.all and resolve them
6	// with decide, then assemble the packet. Every criterion's work is wrapped in a
7	// trace span when a sink is injected. Any thrown error becomes a single
8	// run_error event and stops the run. Junk model output is handled as a gap, not
9	// an error, so the generator never panics on bad model text.
10	
11	import type {
12	  CaseInput,
13	  CriterionResult,
14	  EngineDeps,
15	  EngineEvent,
16	  EvidencePass,
17	} from "./types";
18	import { parseCriteria } from "./parse";
19	import { findEvidence } from "./evidence";
20	import { decide } from "./decide";
21	import { assemble } from "./packet";
22	
23	export * from "./types";
24	export { parseCriteria, parseCriteriaFromPolicy } from "./parse";
25	export { findEvidence, findVerbatimSpan, collapseWs, safeJson } from "./evidence";
26	export { decide } from "./decide";
27	export { assemble } from "./packet";
28	
29	/** Run fn inside a trace span when a sink is set, otherwise run it plain. */
30	async function withSpan<T>(
31	  deps: EngineDeps,
32	  name: string,
33	  kind: string,
34	  attrs: Record<string, unknown>,
35	  fn: (set: (k: string, v: unknown) => void) => Promise<T>,
36	): Promise<T> {
37	  if (deps.trace) return deps.trace.span(name, kind, attrs, fn);
38	  return fn(() => {});
39	}
40	
41	export async function* runEngine(
42	  input: CaseInput,
43	  deps: EngineDeps,
44	): AsyncGenerator<EngineEvent> {
45	  try {
46	    yield { type: "run_start", caseId: input.caseId, service: input.service, policy: input.policy };
47	    deps.trace?.event("run_start", { caseId: input.caseId, service: input.service });
48	
49	    const parsed = await withSpan(deps, "parse", "parse", { caseId: input.caseId }, async (set) => {
50	      const list = await parseCriteria(input, deps.llm);
51	      set("count", list.length);
52	      return list;
53	    });
54	
55	    const criteria =
56	      typeof deps.maxCriteria === "number"
57	        ? parsed.slice(0, Math.max(0, deps.maxCriteria))
58	        : parsed;
59	
60	    yield { type: "criteria_parsed", criteria };
61	
62	    const results: CriterionResult[] = [];
63	    for (const criterion of criteria) {
64	      yield { type: "criterion_start", id: criterion.id };
65	
66	      const [passA, passB] = await withSpan(
67	        deps,
68	        `evidence:${criterion.id}`,
69	        "evidence",
70	        { id: criterion.id },
71	        async (set) => {
72	          const pair = await Promise.all<EvidencePass>([
73	            findEvidence(criterion, input.chart, deps.llm, 1),
74	            findEvidence(criterion, input.chart, deps.llm, 2),
75	          ]);
76	          set("found1", pair[0].found);
77	          set("found2", pair[1].found);
78	          return pair;
79	        },
80	      );
81	
82	      yield { type: "evidence", id: criterion.id, pass: 1, found: passA.found, cite: passA.cite, reasoning: passA.reasoning };
83	      yield { type: "evidence", id: criterion.id, pass: 2, found: passB.found, cite: passB.cite, reasoning: passB.reasoning };
84	
85	      const result = await withSpan(
86	        deps,
87	        `decide:${criterion.id}`,
88	        "decide",
89	        { id: criterion.id },
90	        async (set) => {
91	          const r = decide(criterion, passA, passB);
92	          set("verdict", r.verdict);
93	          return r;
94	        },
95	      );
96	
97	      results.push(result);
98	      yield { type: "criterion_resolved", result };
99	    }
100	
101	    const packet = await withSpan(deps, "packet", "packet", { caseId: input.caseId }, async (set) => {
102	      const p = assemble(input, results);
103	      set("proven", p.provenCount);
104	      set("gap", p.gapCount);
105	      return p;
106	    });
107	
108	    deps.trace?.event("packet_ready", { decision: packet.decision, proven: packet.provenCount, gap: packet.gapCount });
109	    yield { type: "packet_ready", packet };
110	  } catch (err) {
111	    const message = err instanceof Error ? err.message : String(err);
112	    yield { type: "run_error", message };
113	    return;
114	  }
115	}

