export AWS_ACCESS_URL="$(python3 - <<'PY'
import glob, quopri, re
fs = glob.glob('/home/asuran/Downloads/*AWS*access*neatHack.eml')
txt = quopri.decodestring(open(fs[0],'rb').read()).decode('utf-8','replace') if fs else ''
