PY
)"
export CHROME_PATH
[ -n "$AWS_ACCESS_URL" ] && echo "access URL reassembled (token hidden)" || { echo "could not read access URL"; exit 0; }
cat > /tmp/awsrun/drive.mjs <<'EOF'
import puppeteer from 'puppeteer-core';
import { writeFileSync } from 'fs';
const url = process.env.AWS_ACCESS_URL;
const browser = await puppeteer.launch({ executablePath: process.env.CHROME_PATH, headless: 'new', args:['--no-sandbox','--disable-gpu'] });
try {
  const page = await browser.newPage();
  await page.goto(url, { waitUntil:'networkidle2', timeout:45000 });
  const click = async (txts) => page.evaluate((txts)=>{
    const els=[...document.querySelectorAll('button,a,[role=button],summary,div,span,li')];
    for(const t of txts){ const el=els.find(e=>e.offsetParent!==null && e.textContent && e.textContent.trim().toLowerCase().includes(t.toLowerCase()) && e.textContent.trim().length<60); if(el){ el.click(); return t; } }
    return null;
  }, txts);
  const c1 = await click(['Reveal AWS access','Reveal access','Reveal']);
  await new Promise(r=>setTimeout(r,5000));
  const c2 = await click(['CLI / SDK credentials','CLI / SDK','CLI/SDK credentials','CLI']);
  await new Promise(r=>setTimeout(r,5000));
  const text = await page.evaluate(()=>document.body.innerText);
  writeFileSync('/tmp/awsrun/text.txt', text, {mode:0o600});
  const lines = text.split('\n').map(s=>s.trim());
  let keyId='', secret='', token='';
  const kid = text.match(/\b(AKIA|ASIA)[0-9A-Z]{16}\b/); if(kid) keyId=kid[0];
  for(let i=0;i<lines.length;i++){ if(/secret/i.test(lines[i])){ for(let j=i;j<Math.min(i+5,lines.length);j++){ const m=lines[j].match(/^[A-Za-z0-9\/+]{40}$/); if(m){ secret=m[0]; break; } } } }
  for(let i=0;i<lines.length;i++){ if(/session.?token/i.test(lines[i])){ for(let j=i;j<Math.min(i+5,lines.length);j++){ if(lines[j].length>120){ token=lines[j]; break; } } } }
  let env=''; if(keyId) env+=`export AWS_ACCESS_KEY_ID='${keyId}'\n`; if(secret) env+=`export AWS_SECRET_ACCESS_KEY='${secret}'\n`; if(token) env+=`export AWS_SESSION_TOKEN='${token}'\n`;
  writeFileSync('/tmp/awsrun/sponsor.env', env, {mode:0o600});
  console.log(JSON.stringify({ clickedReveal:c1, clickedCli:c2, keyType: keyId? keyId.slice(0,4):'none', secret: secret?'found':'none', token: token?'found':'none', textLen:text.length }));
} finally { await browser.close(); }
EOF
echo "=== drive the reveal ==="
node /tmp/awsrun/drive.mjs 2>&1 | tail -5

